(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.ReadinessLesson,key='fondasi-readiness-v1';
const storage={get(){try{const v=JSON.parse(localStorage.getItem(key)||'null');return v&&v.version===1?v:null;}catch{return null;}},set(v){try{localStorage.setItem(key,JSON.stringify(v));return true;}catch{return false;}}};
const saved=storage.get();let first=core.cleanAnswers(saved?.first),checked=false;
function textElement(tag,text,className){const e=document.createElement(tag);e.textContent=text;if(className)e.className=className;return e;}
function mathElement(tex){const e=document.createElement('span');e.dataset.tex=tex;return e;}
function linkElement(href,label){const e=document.createElement('a');e.href=href;e.textContent=label;return e;}
for(const [gi,group]of core.groups.entries()){$('#readiness-jumps').append(linkElement('#readiness-'+group.id,group.title));const section=document.createElement('section');section.className='readiness-group';section.id='readiness-'+group.id;section.append(textElement('h3',`${gi+1}. ${group.title}`));for(const q of core.questions.filter(q=>q.group===group.id)){const number=core.questions.indexOf(q)+1,box=document.createElement('div');box.className='question';box.append(textElement('h4','Soal '+number));const equation=document.createElement('p');equation.append(mathElement(q.tex));box.append(equation);if(q.kind==='number'){box.append(textElement('p',q.prompt));const label=textElement('label','Jawabanmu untuk soal '+number);label.htmlFor='answer-'+q.id;box.append(label);const input=document.createElement('input');input.id='answer-'+q.id;input.type='text';input.maxLength=80;input.autocomplete='off';input.dataset.question=q.id;input.setAttribute('aria-describedby','feedback-'+q.id);box.append(input);}else{const fieldset=document.createElement('fieldset');fieldset.append(textElement('legend',q.prompt));q.options.forEach((o,i)=>{const label=document.createElement('label');label.className='choice';const input=document.createElement('input');input.type='radio';input.name=q.id;input.value=String(i);input.dataset.question=q.id;if(o.label)input.setAttribute('aria-label',o.label);label.append(input);label.append(o.tex?mathElement(o.tex):document.createTextNode(o.text));fieldset.append(label);});box.append(fieldset);}const feedback=textElement('p','','feedback');feedback.id='feedback-'+q.id;feedback.setAttribute('role','status');box.append(feedback);const firstNote=textElement('p','','first-note');firstNote.id='first-'+q.id;box.append(firstNote);const details=document.createElement('details');details.id='detail-'+q.id;details.hidden=true;details.append(textElement('summary','Baca alasan dan bacaan ulang'));details.append(textElement('p',q.why));for(const [href,title]of q.review){const p=document.createElement('p');p.append(linkElement(href,title+' →'));details.append(p);}box.append(details);section.append(box);}$('#readiness-questions').append(section);}
function collect(){const out={};for(const q of core.questions){if(q.kind==='number')out[q.id]=$('#answer-'+q.id).value;else{const selected=document.querySelector(`[name="${q.id}"]:checked`);out[q.id]=selected?selected.value:'';}}return core.cleanAnswers(out);}
function save(){const ok=storage.set({version:1,answers:collect(),first,checked,note:$('#readiness-note').value});$('#readiness-save').textContent=ok?'Jawaban tersimpan di peramban ini.':'Jawaban belum dapat disimpan di peramban ini; catat hasil jika ingin melanjutkan nanti.';return ok;}
function progress(){const r=core.evaluate(collect());$('#readiness-progress').textContent=`${r.answered} dari 18 soal sudah diisi. ${r.pending} belum dijawab.`;}
function clearFeedback(){for(const q of core.questions){$('#feedback-'+q.id).textContent='';$('#first-'+q.id).textContent='';$('#detail-'+q.id).hidden=true;}$('#readiness-results').hidden=true;$('#results-placeholder').hidden=false;}
function edited(){checked=false;clearFeedback();$('#readiness-message').textContent='Jawaban berubah. Periksa kembali untuk memperbarui umpan balik dan peta bacaan.';progress();save();}
$('#readiness-form').addEventListener('input',edited);
function renderResult(capture,scroll){const answers=collect(),r=core.evaluate(answers);if(r.answered===0){checked=false;clearFeedback();$('#readiness-message').textContent='Isi setidaknya satu jawaban dahulu. Soal yang belum siap dikerjakan boleh dilewati.';save();return;}if(capture)first=core.captureFirst(first,answers);checked=true;const baseline=core.evaluate(first);for(const q of core.questions){const status=r.items[q.id].status,e=$('#feedback-'+q.id);e.className='feedback '+(status==='correct'?'correct':status==='incorrect'||status==='invalid'?'incorrect':'');e.textContent=status==='correct'?'Tepat pada jawaban terbaru.':status==='incorrect'?'Belum tepat. Buka alasan untuk memeriksa konsep dan memilih bacaan ulang.':status==='invalid'?'Format belum dapat diperiksa. Tulis satu bilangan atau pecahan dengan pembagi bukan nol; untuk pilihan jawaban, pilih satu opsi.':'Belum dijawab; tidak dihitung sebagai salah.';$('#detail-'+q.id).hidden=!(status==='correct'||status==='incorrect');const initial=baseline.items[q.id].status;$('#first-'+q.id).textContent=initial==='correct'?'Jawaban pertama yang diperiksa: tepat.':initial==='incorrect'?'Jawaban pertama yang diperiksa: belum tepat.':'';}
$('#current-summary').textContent=`Pemeriksaan terbaru: ${r.correct} tepat, ${r.incorrect} belum tepat, ${r.invalid} perlu perbaikan format, dan ${r.pending} belum dijawab. Total 18 soal.`;const attempted=baseline.correct+baseline.incorrect;$('#first-summary').textContent=`Jawaban pertama yang dapat diperiksa: ${baseline.correct} tepat dari ${attempted} soal yang sudah dicoba. Jawaban terbaru dapat berbeda setelah belajar; soal kosong dan format yang tidak sah belum dicatat sebagai percobaan konsep.`;$('#topic-results').replaceChildren();for(const topic of r.topics){const box=document.createElement('div');box.className='topic-result';box.append(textElement('h3',topic.title));let message;if(topic.correct===2)message='Kedua jawaban terbaru tepat pada dua soal ini. Coba variasi lain untuk menguatkan pemahaman.';else if(topic.pending===2)message='Kedua soal belum dijawab. Belum ada dasar untuk menyimpulkan pemahaman pada kelompok ini.';else message=`${topic.correct} dari 2 jawaban tepat; ${topic.incorrect} belum tepat, ${topic.invalid} perlu diperbaiki formatnya, ${topic.pending} belum dijawab.`;box.append(textElement('p',message));if(topic.invalid)box.append(textElement('p','Perbaiki format jawaban sebelum menarik kesimpulan konsep dari soal tersebut.'));if(topic.review.length){box.append(textElement('p','Bacaan ulang berdasarkan jawaban yang belum tepat:'));for(const [href,title]of topic.review)box.append(linkElement(href,title+' →'));}box.append(linkElement('#readiness-'+topic.id,topic.pending||topic.invalid?'Lanjutkan atau perbaiki isian kelompok ini ↑':'Kembali ke soal kelompok ini ↑'));$('#topic-results').append(box);}$('#readiness-results').hidden=false;$('#results-placeholder').hidden=true;$('#readiness-message').textContent='Peta hasil sudah diperbarui. Baca hasil per kelompok dan pilih bacaan yang sesuai.';progress();save();if(scroll)$('#hasil').scrollIntoView({behavior:'smooth',block:'start'});}
$('#readiness-form').addEventListener('submit',e=>{e.preventDefault();renderResult(true,true);});
const answers=core.cleanAnswers(saved?.answers);for(const q of core.questions){if(q.kind==='number')$('#answer-'+q.id).value=answers[q.id]||'';else if(answers[q.id]!==undefined&&/^\d+$/.test(answers[q.id])&&Number(answers[q.id])<q.options.length){const e=document.querySelector(`[name="${q.id}"][value="${answers[q.id]}"]`);if(/^\d+$/.test(answers[q.id])&&e)e.checked=true;}}
$('#readiness-note').value=typeof saved?.note==='string'?saved.note.slice(0,10000):'';$('#readiness-note').addEventListener('input',()=>{$('#note-save').textContent=save()?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});progress();if(saved?.checked)renderResult(false,false);
$('#reset-readiness').addEventListener('click',()=>{for(const q of core.questions){if(q.kind==='number')$('#answer-'+q.id).value='';else document.querySelectorAll(`[name="${q.id}"]`).forEach(e=>e.checked=false);}first={};checked=false;clearFeedback();progress();save();$('#readiness-message').textContent='Jawaban dan hasil cek sudah dimulai ulang. Catatan rencana belajar tetap tersedia.';$('#cek').scrollIntoView({behavior:'smooth',block:'start'});});
})();